-- Synthetic PostgreSQL example for SQL -> DBML import.
BEGIN;
CREATE TYPE "enrollment_status" AS ENUM ('active', 'completed', 'cancelled');
CREATE TABLE "students" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "email" varchar(255) NOT NULL,
    "full_name" varchar(120) NOT NULL,
    "created_at" timestamp DEFAULT now() NOT NULL,
    CONSTRAINT "pk_students_id" PRIMARY KEY ("id"),
    CONSTRAINT "uq_students_email" UNIQUE ("email")
);
CREATE TABLE "courses" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "title" varchar(160) NOT NULL,
    "published" boolean DEFAULT false NOT NULL,
    "price" numeric(10, 2) DEFAULT 0 NOT NULL,
    CONSTRAINT "pk_courses_id" PRIMARY KEY ("id")
);
CREATE TABLE "lessons" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "course_id" bigint NOT NULL,
    "title" varchar(160) NOT NULL,
    "position" integer NOT NULL,
    CONSTRAINT "pk_lessons_id" PRIMARY KEY ("id")
);
CREATE TABLE "student_profiles" (
    "student_id" bigint NOT NULL,
    "bio" text,
    "github_url" varchar(255),
    CONSTRAINT "pk_student_profiles_student_id" PRIMARY KEY ("student_id")
);
CREATE TABLE "enrollments" (
    "student_id" bigint NOT NULL,
    "course_id" bigint NOT NULL,
    "status" "enrollment_status" NOT NULL,
    "enrolled_at" timestamp DEFAULT 'now()' NOT NULL,
    CONSTRAINT "pk_enrollments_student_id_course_id" PRIMARY KEY ("student_id", "course_id")
);
CREATE UNIQUE INDEX "uq_lesson_position" ON "lessons" ("course_id", "position");
ALTER TABLE "lessons" ADD CONSTRAINT "fk_lessons_course_id_courses_id" FOREIGN KEY ("course_id") REFERENCES "courses" ("id") ON DELETE CASCADE;
ALTER TABLE "student_profiles" ADD CONSTRAINT "fk_student_profiles_student_id_students_id" FOREIGN KEY ("student_id") REFERENCES "students" ("id");
ALTER TABLE "enrollments" ADD CONSTRAINT "fk_enrollments_student_id_students_id" FOREIGN KEY ("student_id") REFERENCES "students" ("id");
ALTER TABLE "enrollments" ADD CONSTRAINT "fk_enrollments_course_id_courses_id" FOREIGN KEY ("course_id") REFERENCES "courses" ("id");
COMMENT ON COLUMN "courses"."price" IS 'Цена в рублях';
COMMENT ON TABLE "student_profiles" IS 'A student may have no profile, but each profile belongs to one student';
COMMIT;
